/**
 * Click Generate Hook
 *
 * Thin wrapper that passes generated timetable data to the post hook.
 * Separates the generation logic from the posting logic.
 *
 * @module useClickGenerate
 */
import { usePostTimeTable } from './usePostTimeTable';

export const useClickGenerate = () => {
	const { appendDataPost } = usePostTimeTable();

	/**
	 * Send the generated timetable data to the API.
	 * @param timetable - Array of daily prayer time objects generated by useGenerateCalender
	 */
	const appendDataGenerate = (timetable: object[]) => {
		appendDataPost(timetable);
	};

	return { appendDataGenerate };
};
